inputs.script:
const VERSION = "REGN_ADAPTER_SINGLE_CALL_TIMING_V1_READ_ONLY";
const cfg = input.config();
const result = {
  version: VERSION,
  scope: "REGN_ADAPTER_ONLY_NO_COMPARATOR_NO_QUEUE",
  requestedDirectTimeoutSeconds: 5,
  adapterAttempts: 1,
  writes: 0,
  liveStagingTouched: false,
  liveWorkerTouched: false
};
const overallStart = Date.now();
let stage = "BINDING_READ";
try {
  const sourceWatch = base.getTable("Source Watch");
  const sw = await sourceWatch.selectRecordAsync(cfg.sourceWatchRecordId);
  if (!sw) throw new Error("Source Watch record not found");
  const companyLinks = sw.getCellValue("Company") || [];
  const adapterLinks = sw.getCellValue("Adapter Registry") || [];
  if (companyLinks.length !== 1 || adapterLinks.length !== 1) {
    throw new Error("Expected exactly one Company and Adapter Registry binding");
  }
  const company = await base.getTable("Companies").selectRecordAsync(companyLinks[0].id);
  const adapter = await base.getTable("Adapter Registry").selectRecordAsync(adapterLinks[0].id);
  if (!company || !adapter) throw new Error("Linked Company or Adapter Registry not found");
  const companyName = company.getCellValueAsString("Name").trim();
  const profile = adapter.getCellValueAsString("Adapter Profile").trim();
  const handler = adapter.getCellValueAsString("Endpoint / Handler")
    .replace(/^pharma-pipeline-pdf-adapter:/i, "").trim();
  if (profile !== "PIPELINE_GENERIC_HTML_V1" || handler !== "/extract/generic/pipeline") {
    throw new Error("Adapter binding is not the expected generic HTML extraction route");
  }
  const sourceUrl = sw.getCellValueAsString("Machine Source URL").trim()
    || sw.getCellValueAsString("Source URL").trim();
  if (!sourceUrl || !companyName) throw new Error("Missing company/source URL");
  const request = new URL("https://pharma-pipeline-pdf-adapter.onrender.com" + handler);
  request.searchParams.set("company", companyName);
  request.searchParams.set("source_url", sourceUrl);
  request.searchParams.set("timeout_seconds", "5");
  result.binding = {
    company: companyName,
    adapterProfile: profile,
    handler,
    sourceHost: new URL(sourceUrl).hostname
  };
  const key = String(input.secret("adapterApiKey") || "");
  if (!key) throw new Error("adapterApiKey secret is blank");
  stage = "ONE_ADAPTER_FETCH";
  const callStart = Date.now();
  console.log("REGN_SINGLE_CALL_STARTED", JSON.stringify({startedAt:new Date().toISOString(), company:companyName, handler, timeoutSeconds:5}));
  const response = await fetch(request.toString(), {
    method: "GET",
    headers: {"Accept":"application/json", "X-Adapter-Key":key}
  });
  result.adapterElapsedMs = Date.now() - callStart;
  result.httpStatus = response.status;
  result.httpOk = response.ok;
  stage = "BODY_READ";
  const body = await response.text();
  result.totalBodyChars = body.length;
  let parsed = null;
  try { parsed = JSON.parse(body); } catch (_) {}
  if (parsed) {
    result.errorDetail = response.ok ? null : String(JSON.stringify(parsed.detail || parsed)).slice(0, 600);
    result.rowCount = Array.isArray(parsed.rows) ? parsed.rows.length : null;
    result.readyForDiscovery = parsed.readyForDiscovery === true;
    result.structuralValidationPass = parsed.summary && parsed.summary.structuralValidationPass === true;
    result.retrievalDiagnostics = parsed.diagnostics ? {
      retrievalMode: parsed.diagnostics.retrievalMode || null,
      routingReason: parsed.diagnostics.routingReason || null,
      directFailure: parsed.diagnostics.directFailure || null
    } : null;
  } else {
    result.nonJsonBodyPrefix = body.slice(0, 180);
  }
  result.status = response.ok ? "ADAPTER_RESPONSE_RECEIVED" : "ADAPTER_HTTP_FAILURE";
} catch(e) {
  result.status = "PROBE_ERROR";
  result.errorStage = stage;
  result.error = String(e && e.message || e).slice(0, 650);
} finally {
  result.totalElapsedMs = Date.now() - overallStart;
  console.log("REGN_SINGLE_CALL_RESULT", JSON.stringify(result));
  output.set("timingDiagnostic", JSON.stringify(result, null, 2));
}
